def modp(n: int, p: int) -> int:
    result = 1
    base = 2 % p
    exp = n
    while exp > 0:
        if exp % 2 == 1:
            result = (result * base) % p
        base = (base * base) % p
        exp //= 2
    return result % p

def modp(n: int, p: int) -> int:
    if p == 1:
        return 0
    result = 1
    base = 2 % p
    exp = n
    while exp > 0:
        if exp % 2 == 1:
            result = (result * base) % p
        base = (base * base) % p
        exp //= 2
    return result

def decode_shift(s: str) -> str:
    result = []
    for ch in s:
        if 'a' <= ch <= 'z':
            shifted = ord(ch) - 5
            if shifted < ord('a'):
                shifted += 26
            result.append(chr(shifted))
        else:
            result.append(ch)
    return ''.join(result)

