def iscube(a: int) -> bool:
    if a < 0:
        a = -a
        return round(a ** (1/3)) ** 3 == a
    return round(a ** (1/3)) ** 3 == a

def iscube(a: int) -> bool:
    """
    Check if number a is a cube of some integer number.
    """
    if a == 0:
        return True
    if a < 0:
        candidate = -round((-a) ** (1/3))
    else:
        candidate = round(a ** (1/3))
    return candidate ** 3 == a

def iscube(a: int) -> bool:
    if a == 0:
        return True
    sign = 1 if a > 0 else -1
    abs_a = abs(a)
    for i in range(1, int(abs_a ** (1/3)) + 2):
        if i * i * i == abs_a:
            return True
    return False

